using System;
using System.Collections.Generic;
using TourCore.Application.Common.Exceptions;
using TourCore.Domain.Tours;
namespace TourCore.Application.Tours { public class TourCommandValidator { public void ValidateAndThrow(TourCommandBase c,bool update){var e=new List<string>();if(c==null)e.Add("Request body is required.");else{if(string.IsNullOrWhiteSpace(c.Name))e.Add("Name is required.");else if(c.Name.Trim().Length>128)e.Add("Name must be 128 characters or less.");if(c.CurrencyId<=0)e.Add("CurrencyId must be greater than zero.");if(!Enum.IsDefined(typeof(TourDateMode),c.DateMode))e.Add("DateMode must be 1 or 2.");if((TourDateMode)c.DateMode==TourDateMode.ContinuousPeriod&&(!c.AvailableDateFrom.HasValue||!c.AvailableDateTo.HasValue))e.Add("AvailableDateFrom and AvailableDateTo are required for ContinuousPeriod.");if((TourDateMode)c.DateMode==TourDateMode.ContinuousPeriod&&c.AvailableDateFrom>c.AvailableDateTo)e.Add("AvailableDateFrom must not be later than AvailableDateTo.");if((TourDateMode)c.DateMode==TourDateMode.SpecificDates&&(c.AvailableDates==null||c.AvailableDates.Count==0))e.Add("AvailableDates must contain at least one date for SpecificDates.");if(!string.IsNullOrWhiteSpace(c.DescriptionUrl)&&c.DescriptionUrl.Trim().Length>2048)e.Add("DescriptionUrl must be 2048 characters or less.");if(update&&!Enum.IsDefined(typeof(TourStatus),((UpdateTourCommand)c).Status))e.Add("Status must be from 1 to 4.");}if(e.Count>0)throw new ValidationException(e);} } }
